// Bug: data may be undefined when API returns empty
module.exports = function sumItems(data) {
  let total = 0;
  data = data || [];
  data.forEach(item => { total += item.value; });
  return total;
};

const sumItems = require('./bug-02-foreach-undefined');

describe('sumItems regression', () => {
  test('returns 0 when called with undefined data', () => {
    expect(sumItems(undefined)).toBe(0);
  });

  test('still sums item values for a valid array', () => {
    expect(sumItems([{ value: 2 }, { value: 3 }])).toBe(5);
  });
});

// Bug: user.profile can be undefined
module.exports = function getUserName(user) {
  return (user.profile?.name ?? "").toUpperCase();
};

const handler = require('./api');

describe('handler regression for missing user.profile', () => {
  it('does not throw when profile is undefined and returns an empty uppercase name', () => {
    expect(() => handler({ id: 1 })).not.toThrow();
    expect(handler({ id: 1 })).toBe('');
  });

  it('still returns the uppercased profile name when present', () => {
    expect(handler({ id: 1, profile: { name: 'alice' } })).toBe('ALICE');
  });
});

